PROJECT_DIR = Path(__file__).resolve().parents[1]
INPUT_DIR = PROJECT_DIR / "input"
OUTPUT_DIR = PROJECT_DIR / "output"
DATA_DIR = OUTPUT_DIR / "data"
METADATA_DIR = OUTPUT_DIR / "metadata"
REPORT_DIR = OUTPUT_DIR / "reports"
QA_DIR = OUTPUT_DIR / "qa"
DASHBOARD_DIR = OUTPUT_DIR / "dashboard"
LOGO_SOURCE = PROJECT_DIR.parents[1] / "dashboard-automation" / "assets" / "logo.png"
MONTHS = {"ตุลาคม": 1, "พฤศจิกายน": 2, "ธันวาคม": 3, "มกราคม": 4, "กุมภาพันธ์": 5, "มีนาคม": 6, "เมษายน": 7, "พฤษภาคม": 8, "มิถุนายน": 9, "กรกฎาคม": 10, "สิงหาคม": 11, "กันยายน": 12}
THAI_MONTHS = {"01": "มกราคม", "02": "กุมภาพันธ์", "03": "มีนาคม", "04": "เมษายน", "05": "พฤษภาคม", "06": "มิถุนายน", "07": "กรกฎาคม", "08": "สิงหาคม", "09": "กันยายน", "10": "ตุลาคม", "11": "พฤศจิกายน", "12": "ธันวาคม"}
CURRENT_ACADEMIC_YEAR = 2569


def text(value: Any, fallback: str = "ไม่ระบุ") -> str:
    value = " ".join(str(value or "").split())
    return value or fallback


def number(value: Any) -> float | None:
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return float(value)
    try:
        return float(str(value).replace(",", "").strip())
    except (TypeError, ValueError):
        return None


def year(value: Any) -> str:
    value = number(value)
    return str(int(value)) if value is not None else text(value)


def student_entry_month(value: Any) -> str:
    parts = str(value or "").split("/")
    return THAI_MONTHS.get(parts[1].zfill(2), "ไม่ระบุ") if len(parts) == 3 else "ไม่ระบุ"


def derived_study_year(entry_year: str, student_id: Any) -> str:
    numeric_year = number(entry_year)
    if numeric_year is None:
        prefix = "".join(character for character in str(student_id or "")[:2] if character.isdigit())
        numeric_year = 2500 + int(prefix) if len(prefix) == 2 else None
    if numeric_year is None:
        return "ไม่ระบุ"
    academic_year = int(numeric_year)
    calculated = CURRENT_ACADEMIC_YEAR - academic_year + 1
    if calculated < 1:
        return "ยังไม่ถึงปีการศึกษา"
    if calculated > 4:
        return "เกิน 4 ปี"
    return f"ปี {calculated}"


def fiscal_year(entry_year: str, entry_month: str) -> str:
    value = number(entry_year)
    if value is None:
        return "ไม่ระบุ"
    return str(int(value) + 1 if entry_month in {"ตุลาคม", "พฤศจิกายน", "ธันวาคม"} else int(value))


def write_json(path: Path, value: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def rows(path: Path, sheet: str) -> list[dict[str, Any]]:
    workbook = load_workbook(path, read_only=True, data_only=True)
    worksheet = workbook[sheet]
    values = list(worksheet.iter_rows(values_only=True))
    workbook.close()
    headers = [text(value, "") for value in values[0]]
    output = []
    for row in values[1:]:
        record = {headers[index]: value for index, value in enumerate(row) if index < len(headers) and headers[index]}
        if any(value not in (None, "") for value in record.values()):
            output.append(record)
    return output


def profile(path: Path) -> list[dict[str, Any]]:
    workbook = load_workbook(path, read_only=True, data_only=True)
    sheets = []
    for worksheet in workbook.worksheets:
        values = list(worksheet.iter_rows(values_only=True))
        nonempty = [row for row in values if any(value not in (None, "") for value in row)]
        headers = [text(value, "") for value in values[0]] if values else []
        sheets.append({
            "name": worksheet.title,
            "rows": len(nonempty),
            "columns": worksheet.max_column,
            "header": [header for header in headers if header],
            "null_cells": sum(value in (None, "") for row in values[1:] for value in row),
        })
    workbook.close()
    return sheets


def count_by(records: list[dict[str, Any]], key: str, limit: int = 15) -> list[dict[str, Any]]:
    values = Counter(text(record.get(key)) for record in records)
    return [{"label": label, "value": value} for label, value in values.most_common(limit)]


def unique_by(records: list[dict[str, Any]], keys: list[str]) -> int:
    return len({tuple(text(record.get(key), "") for key in keys) for record in records})


def write_csv(name: str, records: list[dict[str, Any]]) -> None:
    path = DATA_DIR / name
    if not records:
        path.write_text("", encoding="utf-8")
        return
    with path.open("w", newline="", encoding="utf-8") as handle:
        writer = csv.DictWriter(handle, fieldnames=list(records[0]))
        writer.writeheader()
        writer.writerows(records)


def build_data(files: dict[str, Path]) -> tuple[dict[str, Any], dict[str, list[dict[str, Any]]]]:
    undergraduate = rows(files["education"], "edu_student_current")
    admissions = rows(files["education"], "edu_R012_Program")
    graduate = rows(files["graduate"], "dim_student")
    graduate_enrollment = rows(files["graduate"], "fact_enrollment")
    inbound = rows(files["mobility"], "Inbound_Mobility")
    outbound = rows(files["mobility"], "Outbound_Mobility")
    publications = rows(files["research"], "ผลงานการตีพิมพ์")
    researchers = rows(files["research"], "รายชื่อนักวิจัยในคณะ")
    targets = rows(files["research"], "ค่าเป้าหมาย")
    personnel = rows(files["hr"], "ข้อมูลบุคลากร")
    personnel_history = rows(files["hr"], "จำนวนบุคลากร")
    investment_monthly = rows(files["investment"], "INV_สรุปรายเดือน")
    investment_performance = rows(files["investment"], "INV_ผลตอบแทน")
    investment_assets = rows(files["investment"], "INV_สินทรัพย์")

    education_safe = []
    for row in undergraduate:
        student_id = row.get("รหัสนักศึกษา")
        entry_year = year(row.get("ปีที่เข้าศึกษา"))
        program = text(row.get("หลักสูตร"))
        if text(student_id, "") == "รหัสนักศึกษา" or program == "หลักสูตร":
            continue
        entry_month = student_entry_month(row.get("วันที่เข้าศึกษา"))
        education_safe.append({
            "education_level": text(row.get("ระดับการศึกษา")),
            "program": program,
            "entry_year": entry_year,
            "entry_month": entry_month,
            "entry_fiscal_year": fiscal_year(entry_year, entry_month),
            "study_year": derived_study_year(entry_year, student_id),
            "admission_system": text(row.get("ระบบการสอบเข้า")),
            "student_status": text(row.get("สถานภาพการเป็นนักศึกษา")),
        })
    admissions_safe = [{
        "academic_year": year(row.get("academic_year")),
        "admission_round": text(row.get("admission_round")),
        "program": text(row.get("program_name_short")),
    } for row in admissions]
    graduate_safe = [{
        "education_level": text(row.get("education_level")),
        "program": text(row.get("program_name")),
        "entry_year": year(row.get("entry_year")),
        "program_type": text(row.get("program_type")),
        "thesis_status": text(row.get("thesis_status")),
    } for row in graduate]
    mobility_safe = [{
        "direction": direction,
        "academic_year": year(row.get("academic_year")),
        "month": text(row.get("start_date(M)")),
        "country": text(row.get("partner_country")),
        "university": text(row.get("partner_university")),
        "mobility_type": text(row.get("mobility_type")),
        "duration": text(row.get("duration_raw")),
    } for direction, source in (("ขาเข้า", inbound), ("ขาออก", outbound)) for row in source]
    publication_safe = [{
        "year": year(row.get("ปี")),
        "type": text(row.get("ประเภท")),
        "journal": text(row.get("ชื่อวารสาร")),
    } for row in publications]
    researcher_safe = [{"department": text(row.get("สังกัด"))} for row in researchers]
    personnel_safe = [{
        "status": text(row.get("สถานะบุคลากร")),
        "position": text(row.get("ตำแหน่งงาน")),
        "employment_type": text(row.get("ประเภทบุคลากร")),
        "department": text(row.get("UserDepartment")),
        "work_line": text(row.get("ประเภทสายงาน")),
    } for row in personnel]
    personnel_history_safe = [{
        "year": year(row.get("Year")),
        "month": text(row.get("Month")),
        "work_line": text(row.get("ประเภทสายงาน")),
        "position": text(row.get("ตำแหน่ง")),
        "active": number(row.get("Active")) or 0,
        "inactive": number(row.get("Non-active")) or 0,
    } for row in personnel_history]
    investment_monthly_safe = [{
        "report_date": text(row.get("ReportDate_AD")),
        "year": year(row.get("ปี พ.ศ.")),
        "month": text(row.get("เดือน")),
        "month_order": int(number(row.get("เดือนลำดับ")) or 0),
        "net_asset_value": number(row.get("จำนวนมูลค่าทรัพย์สินสุทธิ")) or 0,
        "nav_per_unit": number(row.get("มูลค่าทรัพย์สินสุทธิต่อหน่วย")) or 0,
        "period_return": number(row.get("ผลตอบแทนช่วงรายงาน %")) or 0,
    } for row in investment_monthly]
    investment_assets_safe = [{
        "report_date": text(row.get("ReportDate_AD")),
        "year": year(row.get("ปี พ.ศ.")),
        "month": text(row.get("เดือน")),
        "category": text(row.get("Asset_Category")),
        "risk_group": text(row.get("Risk_Group")),
    } for row in investment_assets]
    latest_investment = max(investment_monthly_safe, key=lambda row: row["report_date"])
    latest_date = latest_investment["report_date"]
    latest_assets = [row for row in investment_assets_safe if row["report_date"] == latest_date]
    performance_safe = [{
        "report_date": text(row.get("ReportDate_AD")),
        "year": year(row.get("ปี พ.ศ.")),
        "month": text(row.get("เดือน")),
        "label": text(row.get("Client_Name")),
        "value": number(row.get("PM (%)")) or 0,
        "benchmark": number(row.get("BenchMark")) or 0,
    } for row in investment_performance]

    safe_files = {
        "education-summary.csv": education_safe,
        "graduate-summary.csv": graduate_safe,
        "mobility-summary.csv": mobility_safe,
        "research-summary.csv": publication_safe,
        "personnel-summary.csv": personnel_safe,
        "investment-monthly-summary.csv": investment_monthly_safe,
    }
    for name, records in safe_files.items():
        write_csv(name, records)

    data = {
        "education": {
            "current_students": len(education_safe), "by_level": count_by(education_safe, "education_level"),
            "by_program": count_by(education_safe, "program"), "by_study_year": count_by(education_safe, "study_year"),
            "by_admission_system": count_by(education_safe, "admission_system"), "by_entry_year": count_by(education_safe, "entry_year"),
            "students": education_safe, "current_academic_year": str(CURRENT_ACADEMIC_YEAR),
            "admissions_by_year": count_by(admissions_safe, "academic_year"), "admission_rounds": count_by(admissions_safe, "admission_round"),
            "graduate_students": len(graduate_safe), "graduate_by_program": count_by(graduate_safe, "program"),
            "graduate_enrollment_records": len(graduate_enrollment), "graduate_records": graduate_safe,
        },
        "mobility": {
            "inbound": len(inbound), "outbound": len(outbound), "by_direction": count_by(mobility_safe, "direction"),
            "by_country": count_by(mobility_safe, "country"), "by_university": count_by(mobility_safe, "university"),
            "by_type": count_by(mobility_safe, "mobility_type"), "by_year": count_by(mobility_safe, "academic_year"), "records": mobility_safe,
        },
        "research": {
            "publications": len(publication_safe), "researchers": unique_by(researcher_safe, ["department"]),
            "researcher_roster": len(researchers), "by_type": count_by(publication_safe, "type"),
            "by_year": count_by(publication_safe, "year"), "by_researcher_department": count_by(researcher_safe, "department"),
            "targets": [{"year": year(row.get("ปี")), "metric": text(row.get("ระดับของการตีพิมพ์")), "target": number(row.get("ค่าเป้าหมาย"))} for row in targets],
            "records": publication_safe, "roster": researcher_safe,
        },
        "hr": {
            "current_records": len(personnel_safe), "active_status_records": sum(row["status"] == "ปกติ" for row in personnel_safe),
            "by_work_line": count_by(personnel_safe, "work_line"), "by_position": count_by(personnel_safe, "position"),
            "by_department": count_by(personnel_safe, "department"), "by_status": count_by(personnel_safe, "status"),
            "history_years": count_by(personnel_history_safe, "year"),
            "latest_history_year": max((row["year"] for row in personnel_history_safe if row["year"] != "ไม่ระบุ"), default="ไม่ระบุ"),
            "records": personnel_safe, "history": personnel_history_safe,
        },
        "investment": {
            "latest": latest_investment, "monthly": sorted(investment_monthly_safe, key=lambda row: row["report_date"]),
            "latest_asset_records": len(latest_assets), "assets_by_category": count_by(latest_assets, "category"),
            "assets_by_risk": count_by(latest_assets, "risk_group"),
            "assets": investment_assets_safe,
            "performance": sorted([row for row in performance_safe if row["report_date"] == latest_date], key=lambda row: row["value"], reverse=True),
            "performance_records": performance_safe,
        },
    }
    return data, safe_files


def dashboard_html(data: dict[str, Any]) -> str:
    payload = json.dumps(data, ensure_ascii=False, separators=(",", ":"))
