def main() -> None:
    files = {"education": INPUT_DIR / "1.Current Students _ Admissions .xlsx", "graduate": INPUT_DIR / "2.Current Graduate Student.xlsx", "mobility": INPUT_DIR / "3.Mobility Overview.xlsx", "research": INPUT_DIR / "4.Research Publication Performance.xlsx", "hr": INPUT_DIR / "5.Workforce _ Personnel Overview .xlsx", "investment": INPUT_DIR / "การลงทุน_ฐานใหม่.xlsx"}
