        {"check": "personnel history snapshot 2569 สิงหาคม", "expected": 129, "actual": sum(row["active"] for row in data["hr"]["history"] if row["year"] == "2569" and row["month"] == "สิงหาคม"), "result": "PASS" if sum(row["active"] for row in data["hr"]["history"] if row["year"] == "2569" and row["month"] == "สิงหาคม") == 129 else "FAIL"},
